package com.tripmateai.controller; import com.tripmateai.dto.request.ai.AiTripPlanRequest; import com.tripmateai.dto.response.ApiResponse; import com.tripmateai.dto.response.ai.AiTripPlanResponse; import com.tripmateai.service.AiTripPlannerService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
